{"content": "import fs from 'node:fs'
import { chromium } from '@playwright/test'

const BASE = 'http://127.0.0.1:4173'
const ROOT = '/home/zhaodan/work/NodeJsProjects/agent-hub-web'
const OUT = `${ROOT}/.tmp/pixel/shots`
fs.mkdirSync(OUT, { recursive: true })

const browser = await chromium.launch({ args: ['--no-proxy-server'] })
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const page = await ctx.newPage()
page.on('pageerror', (e) => console.log('[pageerror]', e.message.slice(0, 200)))

async function shot(name, wait = 500) {
  await page.waitForTimeout(wait)
  await page.screenshot({ path: `${OUT}/${name}.png` })
  console.log('shot', name)
}

async function appLogin(p) {
  await p.goto(`${BASE}/login`)
  await p.waitForSelector('input')
  await p.getByPlaceholder('you@example.com').fill('admin@example.com')
  await p.getByPlaceholder('至少 8 位').fill('12345678')
  await p.getByRole('button', { name: '登录', exact: true }).click()
  await p.waitForURL(/\/chat/, { timeout: 20000 })
  await p.waitForTimeout(1000)
}

async function go(path, name, wait = 900) {
  await page.goto(`${BASE}${path}`)
  await page.waitForTimeout(wait)
  await shot(name, 0)
}

// ===== App（生产构建 + mock） =====
await page.goto(`${BASE}/login`)
await page.waitForSelector('input')
await shot('app-01-login', 300)
await page.goto(`${BASE}/register`)
await page.waitForSelector('input')
await shot('app-01b-register', 300)

await appLogin(page)
await shot('app-02-chat-empty')

const firstSession = page.locator('.session').first()
await firstSession.click()
await shot('app-03-chat-history', 1200)

const composer = page.getByRole('textbox', { name: '输入消息' })
await composer.fill('整理一份 Q3 客服周报，并把结果发到 Slack')
await page.getByRole('button', { name: '发送' }).click()
await page.waitForTimeout(2000)
await shot('app-04-chat-streaming', 0)
await page.waitForTimeout(14000)
await shot('app-05-chat-done', 0)

// 审批卡交互：滚动到审批卡
await page.getByText('Slack · 发送消息').first().scrollIntoViewIfNeeded().catch(() => undefined)
await shot('app-05b-chat-approval', 400)

await go('/agents', 'app-06-agents')
await go('/tasks', 'app-07-tasks')
await go('/knowledge', 'app-08-knowledge')
await go('/workflows', 'app-09-workflows')
await go('/workflows/new', 'app-10-workflow-new')
await go('/settings', 'app-11-settings')

// 设置页滚动：依次滚动内部滚动容器
const scroller = page.locator('.settings-scroll, .page-scroll, main, .settings').first()
for (let i = 1; i <= 3; i++) {
  await page.mouse.move(700, 500)
  await page.mouse.wheel(0, 900)
  await shot(`app-11-settings-scroll-${i}`, 400)
}

await go('/admin', 'app-13-admin-overview')
for (const [path, name] of [
  ['/admin/users', 'app-14-admin-users'],
  ['/admin/roles', 'app-15-admin-roles'],
  ['/admin/menus', 'app-16-admin-menus'],
  ['/admin/dictionaries', 'app-17-admin-dict'],
  ['/admin/audit', 'app-18-admin-audit'],
  ['/admin/settings', 'app-19-admin-settings'],
]) {
  await go(path, name)
}

// 命令面板
await page.goto(`${BASE}/chat`)
await page.waitForTimeout(600)
await page.keyboard.press('Control+k')
await shot('app-20-palette', 500)
await page.keyboard.press('Escape')

// 暗色主题
await page.evaluate(() => localStorage.setItem('agent-hub-theme', 'dark'))
await page.reload()
await page.waitForTimeout(1000)
await shot('app-21-dark-chat', 400)
await page.evaluate(() => localStorage.setItem('agent-hub-theme', 'light'))

// 窄屏（运行轨迹抽屉）
const narrow = await browser.newContext({ viewport: { width: 1024, height: 800 } })
const np = await narrow.newPage()
await appLogin(np)
await np.waitForTimeout(800)
await np.screenshot({ path: `${OUT}/app-22-narrow-chat.png` })
console.log('shot app-22-narrow-chat')

// 移动端
const mobile = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true })
const mp = await mobile.newPage()
await appLogin(mp)
await mp.waitForTimeout(800)
await mp.screenshot({ path: `${OUT}/app-23-mobile-chat.png` })
console.log('shot app-23-mobile-chat')

// ===== 原型 =====
const proto = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const pp = await proto.newPage()

async function protoShot(file, name, prepare) {
  await pp.goto(`file://${ROOT}/docs/prototypes/${file}`)
  await pp.waitForTimeout(600)
  if (prepare) await pp.evaluate(prepare)
  await pp.waitForTimeout(600)
  await pp.screenshot({ path: `${OUT}/${name}.png` })
  console.log('shot', name)
}

await protoShot('ui-v7.html', 'proto-v7-chat')

for (const p of ['agents', 'workflows', 'tasks', 'knowledge']) {
  await protoShot('ui-v7-pages.html', `proto-v7-${p}`, `showPage('${p}')`)
}
await protoShot('ui-v7-pages.html', 'proto-v7-settings', "showPage('settings')")

for (const p of ['overview', 'users', 'roles', 'menus', 'dict', 'audit', 'system']) {
  await protoShot('ui-v8-admin.html', `proto-v8-${p}`, `showPage('${p}')`)
}

await browser.close()
console.log('done')
", "file_path": ".tmp/pixel/shoot.mjs"}

