/* ============================================================
   Agent Hub UI prototype v7 — other pages
   npm-free, offline single file. All icons are inline symbols.
   ============================================================ */

/* ---------- tokens ---------- */
:root{
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
               "Hiragino Sans GB", "Noto Sans SC", "Source Han Sans SC",
               "Microsoft YaHei", sans-serif;
  --font-mono: ui-monospace, "SF Mono", "JetBrains Mono", "Cascadia Mono",
               "Roboto Mono", Menlo, Consolas, monospace;

  --paper:#F0EFE8;
  --paper-2:#E9E7DD;
  --surface:#FBFAF5;
  --surface-2:#F4F3EC;
  --ink:#141B20;
  --ink-2:#4F5B63;
  --ink-3:#606B72;
  --line:#D7D5C9;
  --line-2:#E3E1D6;

  --prussian:#17465E;
  --prussian-soft:#E4ECEF;
  --amber:#A9741F;
  --amber-text:#8A5D14;
  --amber-soft:#F3E9D3;
  --red:#9C3A2B;
  --red-soft:#F6E5E0;
  --green:#3D6A4E;
  --green-soft:#E4EDE6;
  --mcp:#5A4E72;
  --mcp-soft:#ECE8F1;

  --kind-vector:#2E6485;
  --kind-a2a:#2E746E;
  --kind-a2a-soft:#E0EEEB;

  --btn-bg:#141B20;
  --btn-fg:#FBFAF5;

  --shadow-sm:0 1px 2px rgba(20,27,32,.05);
  --shadow-md:0 1px 2px rgba(20,27,32,.04), 0 10px 28px -18px rgba(20,27,32,.35);
  --shadow-lg:0 24px 60px -28px rgba(20,27,32,.38);

  --sidebar-w:288px;
  --sidebar-rail:56px;
  --trace-w:332px;
}

html[data-theme="dark"]{
  --paper:#0F1418;
  --paper-2:#141A1F;
  --surface:#171F24;
  --surface-2:#1A2329;
  --ink:#E8E7DF;
  --ink-2:#A3AEB4;
  --ink-3:#85929A;
  --line:#2A353C;
  --line-2:#212B31;

  --prussian:#93BED1;
  --prussian-soft:rgba(147,190,209,.12);
  --amber:#D4A04A;
  --amber-text:#E0B76E;
  --amber-soft:rgba(212,160,74,.13);
  --red:#DE907E;
  --red-soft:rgba(222,144,126,.12);
  --green:#8DBBA0;
  --green-soft:rgba(141,187,160,.12);
  --mcp:#B3A4C9;
  --mcp-soft:rgba(179,164,201,.12);

  --kind-vector:#8FB8CC;
  --kind-a2a:#8CC7BF;
  --kind-a2a-soft:rgba(140,199,191,.12);

  --btn-bg:#E8E7DF;
  --btn-fg:#10171B;

  --shadow-sm:0 1px 0 rgba(255,255,255,.03);
  --shadow-md:0 1px 0 rgba(255,255,255,.03), 0 16px 40px -24px rgba(0,0,0,.9);
  --shadow-lg:0 28px 72px -30px rgba(0,0,0,.95);
}

/* ---------- base ---------- */
*,*::before,*::after{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  font-family:var(--font-sans);
  font-size:14px;
  line-height:1.5;
  color:var(--ink);
  background:var(--paper);
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
  overflow:hidden;
}
button{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:pointer}
a{color:inherit;text-decoration:none}
ul,ol,dl,dd{margin:0;padding:0;list-style:none}
h1,h2,h3,h4,p{margin:0}
svg{display:block}
:focus-visible{outline:2px solid var(--prussian);outline-offset:2px;border-radius:3px}
::selection{background:var(--amber-soft);color:var(--ink)}

*{scrollbar-width:thin;scrollbar-color:var(--line) transparent}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{
  background:var(--line);
  border:3px solid transparent;
