/* ---------- base ---------- */
*,*::before,*::after{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  font-family:var(--font-sans);
  font-size:14px;
  line-height:1.5;
  color:var(--ink);
  background:var(--paper);
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
  overflow:hidden;
}
button{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:pointer}
a{color:inherit;text-decoration:none}
ul,ol,dl,dd{margin:0;padding:0;list-style:none}
h1,h2,h3,h4,p{margin:0}
svg{display:block}
:focus-visible{outline:2px solid var(--prussian);outline-offset:2px;border-radius:3px}
::selection{background:var(--amber-soft);color:var(--ink)}

*{scrollbar-width:thin;scrollbar-color:var(--line) transparent}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{
  background:var(--line);
  border:3px solid transparent;
  background-clip:content-box;
  border-radius:99px;
}
::-webkit-scrollbar-thumb:hover{background-color:var(--ink-3)}

.ic{
  width:18px;height:18px;flex:none;
  fill:none;stroke:currentColor;stroke-width:1.6;
  stroke-linecap:round;stroke-linejoin:round;
}
.mono{font-family:var(--font-mono);font-variant-numeric:tabular-nums}
.sr-only{
  position:absolute;width:1px;height:1px;padding:0;margin:-1px;
  overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0;
}

/* ---------- app shell ---------- */
.app{
  display:grid;
  grid-template-columns:var(--sidebar-w) minmax(0,1fr) var(--trace-w);
  height:100dvh;
  min-height:0;
  transition:grid-template-columns .22s ease;
}
.app.trace-collapsed{grid-template-columns:var(--sidebar-w) minmax(0,1fr) 0px}
.app.trace-collapsed .trace{opacity:0;pointer-events:none;overflow:hidden}
.app.sidebar-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr) var(--trace-w)}
.app.sidebar-collapsed.trace-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr) 0px}

/* ============================================================
   SIDEBAR — single column, DSH-style
   ============================================================ */

/* ---------- responsive ---------- */
@media (max-width:1280px){
  :root{--sidebar-w:272px;--trace-w:304px}
  .stream-inner{padding:26px 28px 14px}
  .composer-wrap{padding:8px 24px 12px}
  .chat-head{padding:0 24px}
}

@media (max-width:1180px){
  .app{grid-template-columns:var(--sidebar-w) minmax(0,1fr)}
  .app.sidebar-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr)}
  .app.trace-collapsed{grid-template-columns:var(--sidebar-w) minmax(0,1fr)}
  .app.sidebar-collapsed.trace-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr)}
  .trace{
    position:fixed;right:0;top:68px;bottom:0;
    z-index:60;
    width:var(--trace-w);
    box-shadow:-24px 0 48px -32px rgba(0,0,0,.4);
    transform:translateX(101%);
    transition:transform .22s ease;
  }
  .app.trace-open .trace{transform:translateX(0)}
  .app.trace-collapsed .trace{opacity:1;pointer-events:auto}
}

@media (max-width:900px){
  .app,
  .app.sidebar-collapsed,
  .app.trace-collapsed,
  .app.sidebar-collapsed.trace-collapsed{grid-template-columns:minmax(0,1fr)}
  .sidebar{
    position:fixed;left:0;top:0;bottom:0;
    width:min(288px,86vw);
    z-index:80;
    transform:translateX(-100%);
    transition:transform .22s ease;
    box-shadow:24px 0 48px -32px rgba(0,0,0,.45);
  }
  .app.sidebar-open .sidebar{transform:none}
  .mobile-sidebar-btn{display:grid}
  .sidebar-scrim{
    display:block;position:fixed;inset:0;z-index:75;
    background:rgba(20,27,32,.38);
    opacity:0;pointer-events:none;
    transition:opacity .2s;
  }
  .app.sidebar-open .sidebar-scrim{opacity:1;pointer-events:auto}
  .stream-inner{padding:22px 20px 12px}
  .composer-wrap{padding:8px 16px 12px}
  .chat-head{padding:0 16px;gap:12px}
}

@media (max-width:760px){
  .app{height:100dvh}
  .chat-head{min-height:60px}
  .chat-sub{display:none}
  .chat-actions .status-chip{display:none}
  .stream-inner{padding:18px 14px 10px}
  .entry{padding-left:38px}
  .thread::before{left:15px}
  .node{left:11.5px}
  .thread-foot{margin-left:38px}
  .composer-wrap{padding:6px 10px 10px}
  .composer-meta .keyhint{display:none}
  .trace{width:min(340px,88vw);top:60px;bottom:0}
  .tool-args{display:none}
  .data-table{font-size:12px}
  .prose h3{font-size:17px}
}

/* ============================================================
   v2 components
   ============================================================ */

/* turns */
.turn + .turn{margin-top:30px}

/* process cards: tool / vector search */
.entry-proc{margin-bottom:14px}
.entry-proc .node{border-radius:2px}
.kind{
  display:inline-flex;align-items:center;justify-content:center;flex:none;
  height:17px;padding:0 5px;
  border:1px solid var(--line);
  border-radius:3px;
  background:var(--surface-2);
  color:var(--ink-3);
  font-size:9.5px;font-weight:500;
  letter-spacing:.02em;
  white-space:nowrap;
}
.kind-tool .node{border-color:var(--kind-tool);background:var(--surface)}
.kind-skill .kind{background:var(--kind-skill-soft);color:var(--kind-skill);border-color:transparent}
.kind-vector .kind{background:var(--kind-vector-soft);color:var(--kind-vector);border-color:transparent}
.kind-tool .kind{background:var(--kind-tool-soft);color:var(--amber-text);border-color:transparent}
.kind-mcp .kind{background:var(--kind-mcp-soft);color:var(--kind-mcp);border-color:transparent}
.kind-vector .node{border-color:var(--kind-vector);background:var(--kind-vector-soft)}
.kind-tool .tool-card{border-left:2px solid var(--kind-tool)}
.kind-vector .tool-card{border-left:2px solid var(--kind-vector)}
.tool-card summary{gap:8px}
.vector-meta{
  padding-bottom:5px;
  font-family:var(--font-mono);
  font-size:9.5px;color:var(--ink-3);
}
.vhit{padding:6px 0;border-bottom:1px dashed var(--line-2);font-size:12px}
.vhit:last-of-type{border-bottom:0}
.vhit-main{display:flex;align-items:baseline;gap:8px}
.vhit-title{flex:1;min-width:0;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.vhit-score{font-family:var(--font-mono);font-size:10.5px;color:var(--kind-vector)}
.vhit-sub{
  margin-top:2px;
  font-family:var(--font-mono);
  font-size:9.5px;color:var(--ink-3);
}

/* A2A delegation group */
.delegation{
  border:1px solid var(--line);
  border-left:3px solid var(--kind-a2a);
  border-radius:6px;
  background:var(--surface);
  box-shadow:var(--shadow-sm);
  overflow:hidden;
}
.delegation-head{
  display:flex;align-items:center;gap:7px;flex-wrap:wrap;
  padding:10px 14px;
  border-bottom:1px solid var(--line-2);
  background:var(--surface-2);
}
.delegation-title{font-size:12.5px;font-weight:650;letter-spacing:-.005em}
.delegation-head .tag{color:var(--kind-a2a);background:var(--kind-a2a-soft);border-color:transparent}
.delegation-count{font-size:10.5px;color:var(--ink-3)}
.delegation-head .spacer{flex:1}
.delegation-state{font-family:var(--font-mono);font-size:9.5px;color:var(--ink-3)}
.a2a-row{
  display:flex;align-items:flex-start;gap:10px;
  padding:12px 14px;
  border-bottom:1px solid var(--line-2);
}
.a2a-row + .a2a-row{border-bottom:0}
.a2a-row-ident{flex:1;min-width:0}
.a2a-row-ident .a2a-name{font-size:12.5px}
.a2a-row-ident .a2a-task{font-size:11.5px;margin-top:2px}
.a2a-row-state{
  display:flex;flex-direction:column;align-items:flex-end;gap:3px;
  flex:none;padding-top:1px;
}
.a2a-row-meta{font-family:var(--font-mono);font-size:9px;color:var(--ink-3);white-space:nowrap}
.a2a-status.is-done{color:var(--green)}
.a2a-row-result{
  display:flex;align-items:center;gap:5px;
  margin-top:6px;
  font-size:10.5px;color:var(--green);
}

