{"command": "cd docs/prototypes && node -e "
const fs=require('fs');
const files=['ui-v7.html','ui-v7-pages.html','ui-v8-admin.html'];
const map=new Map();
for(const f of files){
  const html=fs.readFileSync(f,'utf8');
  for(const m of html.matchAll(/<symbol id=\"(i-[a-z0-9-]+)\"[^>]*>([\s\S]*?)<\/symbol>/g)){
    if(!map.has(m[1])) map.set(m[1], m[0]);
  }
}
console.log('symbols:', map.size);
fs.writeFileSync('/tmp/sprite.html', [...map.values()].join('\n'));
console.log([...map.keys()].join(' '));
"", "description": "提取原型图标 sprite 并集"}

