  padding: 8px 12px;
  border-radius: 6px;
  background: var(--btn-bg);
  color: var(--btn-fg);
  font-size: 12px;
  font-weight: 600;
}

.skip-link:focus {
  top: 12px;
}

@media (max-width: 900px) {
  .app-main {
    grid-column: 1;
  }
}
</style>
