.facts div {
  min-width: 0;
}

.facts dt {
  color: var(--ink-3);
  font-size: 10px;
}

.facts dd {
  margin: 1px 0 0;
  overflow-wrap: anywhere;
  color: var(--ink);
  font-size: 11.5px;
}

.risk {
  font-weight: 600;
}

.risk-write {
  color: var(--amber-text);
}

.risk-destructive {
  color: var(--red);
}

.is-expired {
  color: var(--red);
}

.payload {
  margin-top: 9px;
  border-top: 1px dashed var(--line);
  padding-top: 8px;
}

.payload-empty {
  margin: 9px 0 0;
  color: var(--ink-3);
  font-size: 10.5px;
}

.payload summary {
  cursor: pointer;
  color: var(--ink-3);
  font-size: 10.5px;
  user-select: none;
}

.mask-note {
  margin-left: 6px;
  color: var(--amber-text);
}

.payload-body {
  max-height: 200px;
  margin: 7px 0 0;
  padding: 8px 9px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--surface-2);
  color: var(--ink-2);
  font-size: 10.5px;
  line-height: 1.55;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
}

.btn {
  height: 30px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--surface);
  color: var(--ink-2);
  font-size: 12px;
  font-weight: 550;
}

.btn:hover:not(:disabled) {
  border-color: var(--ink-3);
  color: var(--ink);
}

.btn.primary {
  border-color: var(--prussian);
  background: var(--prussian);
  color: var(--surface);
}

.btn.primary:hover:not(:disabled) {
  filter: brightness(1.06);
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

.resolved {
  margin: 10px 0 0;
  color: var(--ink-3);
  font-size: 11px;
}
</style>

.thread-foot .mono{font-size:10px}
.thread-foot::before{
  content:"";
  width:18px;height:1px;background:var(--line);
}

/* ---------- composer ---------- */
.composer-wrap{
  flex:none;
  padding:10px 32px 14px;
  background:var(--paper);
}
.composer-inner{max-width:812px;margin:0 auto}
.composer{
  border:1px solid var(--line);
  border-radius:9px;
  background:var(--surface);
  box-shadow:var(--shadow-md);
  transition:border-color .15s;
}
.composer:focus-within{border-color:var(--ink-3)}
.composer textarea{
  display:block;width:100%;
  min-height:48px;max-height:168px;
  padding:13px 15px 4px;
  border:0;outline:none;resize:none;
  background:transparent;
  color:var(--ink);
  font:inherit;font-size:14px;line-height:1.65;
}
.composer textarea::placeholder{color:var(--ink-3)}
.composer-bar{
  display:flex;align-items:center;gap:6px;
  padding:5px 8px 7px 9px;
}
.composer-tool{
  display:inline-flex;align-items:center;gap:5px;
  height:27px;padding:0 8px;
  border-radius:4px;
  color:var(--ink-3);
  font-size:11.5px;
  transition:background .15s,color .15s;
}
.composer-tool:hover{background:var(--surface-2);color:var(--ink)}
.composer-tool .ic{width:14px;height:14px}
.model-chip{
  display:inline-flex;align-items:center;gap:5px;
  height:23px;padding:0 7px;
  margin-left:2px;
  border:1px solid var(--line-2);
  border-radius:4px;
  font-family:var(--font-mono);
  font-size:10px;color:var(--ink-3);
  white-space:nowrap;
}
.model-chip .dot{width:4px;height:4px;background:var(--green)}
.composer-bar .spacer{flex:1}
.send{
  display:grid;place-items:center;
  width:32px;height:32px;
  border-radius:6px;
  background:var(--btn-bg);
  color:var(--btn-fg);
  transition:opacity .15s,background .15s;
}
.send:hover{background:var(--prussian)}
html[data-theme="dark"] .send:hover{background:var(--amber);color:#141B20}
.send .ic{width:16px;height:16px;stroke-width:2}
.send .ic-stop{display:none;width:14px;height:14px}
.send.is-stop{background:var(--red);color:#FBFAF5}
.send.is-stop:hover{background:var(--red)}
html[data-theme="dark"] .send.is-stop{background:var(--red);color:#141B20}
html[data-theme="dark"] .send.is-stop:hover{background:var(--red)}
.send.is-stop .ic-send{display:none}
.send.is-stop .ic-stop{display:block;fill:currentColor;stroke:none}
.send.is-disabled{opacity:.35;cursor:not-allowed}
.status-chip:disabled{cursor:default}
.composer-hint{
  display:flex;align-items:center;gap:6px;flex-wrap:wrap;
  margin-top:7px;
  padding:0 3px;
  font-size:10.5px;color:var(--ink-3);
}
.composer-hint .spacer{flex:1}
kbd{
  display:inline-block;
  padding:1px 4px;
  border:1px solid var(--line);
  border-bottom-width:2px;
  border-radius:3px;
  background:var(--surface);
  font-family:var(--font-mono);
  font-size:9.5px;
  color:var(--ink-2);
  line-height:1.4;
}

/* ============================================================
   TRACE PANEL
   ============================================================ */
.trace{
  display:flex;flex-direction:column;min-height:0;
  background:var(--surface);

/* ---------- approval card ---------- */
.approval-card{
  border:1px solid var(--line);
  border-left:3px solid var(--kind-approval);
  border-radius:6px;
  background:var(--surface);
  box-shadow:var(--shadow-sm);
  overflow:hidden;
}
.approval-head{
  display:flex;align-items:center;gap:8px;
  padding:13px 15px 0;
}
.approval-head .ic{width:15px;height:15px;color:var(--kind-approval)}
.approval-title{font-size:13px;font-weight:650;letter-spacing:-.005em}
.approval-head .status-chip{margin-left:auto;height:22px;font-size:10.5px;padding:0 7px}
.approval-body{padding:8px 15px 14px}
.approval-action{font-size:13.5px;line-height:1.6;color:var(--ink)}
.approval-action b{font-weight:650}
.risk-list{
  display:grid;grid-template-columns:auto 1fr;
  gap:3px 12px;
  margin-top:11px;
  font-size:11.5px;
}
.risk-list dt{color:var(--ink-3)}
.risk-list dd{color:var(--ink-2)}
.approval-actions{
  display:flex;align-items:center;gap:8px;
  padding:10px 15px;
  border-top:1px solid var(--line-2);
  background:var(--surface-2);
}
.approval-actions .spacer{flex:1}
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:6px;
  height:31px;padding:0 13px;
  border-radius:5px;
  font-size:12.5px;font-weight:550;
  transition:background .15s,color .15s,border-color .15s;
  white-space:nowrap;
}
.btn .ic{width:14px;height:14px}
.btn-primary{background:var(--btn-bg);color:var(--btn-fg);border:1px solid var(--btn-bg)}
.btn-primary:hover{background:var(--prussian);border-color:var(--prussian);color:#FBFAF5}
html[data-theme="dark"] .btn-primary:hover{background:var(--amber);border-color:var(--amber);color:#141B20}
.btn-outline{background:transparent;color:var(--ink-2);border:1px solid var(--line)}
.btn-outline:hover{color:var(--ink);border-color:var(--ink-3)}
.btn[disabled]{opacity:.42;cursor:not-allowed}
.approval-card.is-resolved .approval-actions{display:none}
.approval-card.is-resolved{border-left-color:var(--green)}
.approval-card.is-resolved .approval-head .ic{color:var(--green)}
.resolved-note{
  display:none;
  align-items:center;gap:7px;
  padding:10px 15px;
  border-top:1px solid var(--line-2);
  background:var(--green-soft);
  font-size:11.5px;color:var(--green);
}
.approval-card.is-resolved .resolved-note{display:flex}
.resolved-note .ic{width:14px;height:14px}

/* thread footer */
.thread-foot{
  display:flex;align-items:center;gap:8px;
  margin-left:52px;
  padding-top:2px;
  font-size:11px;color:var(--ink-3);
}
.thread-foot .mono{font-size:10px}
.thread-foot::before{
  content:"";
  width:18px;height:1px;background:var(--line);
}

/* ---------- composer ---------- */

