  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--surface-2);
  color: var(--ink-2);
  font-size: 10.5px;
  line-height: 1.55;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.risk {
  font-weight: 600;
}

.approval-card.is-resolved .resolved-note {
  background: var(--surface-2);
  color: var(--ink-2);
}
</style>
'''
